import os
from google.adk.agents import Agent

def lookup_status(reference: str) -> dict:
    return {"reference": reference, "status": "synthetic"}

root_agent = Agent(name="operations_router", model=os.environ.get("MODEL_ID", "gemini-3.5-flash"), instruction="Use lookup_status and report only its returned facts.", tools=[lookup_status])

